/* MSKBA · Home / Venues Arena v3 · desktop composition only.
   Paste at the END of component venues-scene-v3 CSS in Filament.
   Earlier CSS stays intact. Tablet/mobile are not changed. */
@media (min-width: 1100px) {
  /* Let foreground escape the section's stacking context and overlap Hero. */
  .mskba-page-builder .mskba-v3-venues {
    isolation: auto;
    z-index: auto;
    overflow: visible;
  }

  /* Arena/court remain below Hero; the hero card itself remains interactive. */
  .mskba-page-builder .mskba-v3-venues__scene {
    z-index: 0;
    overflow: hidden;
  }
  .mskba-page-builder .mskba-hero-scene {
    position: relative;
    z-index: 10;
  }

  /* Foreground can extend ABOVE the Hero card without being clipped. */
  .mskba-page-builder .mskba-v3-venues__foreground {
    z-index: 20;
    inset: calc(-1 * var(--v3-hero-bleed)) 0 0;
    overflow: visible;
    pointer-events: none;
  }
  .mskba-page-builder .mskba-v3-venues__container {
    z-index: 21;
    grid-template-columns: minmax(0, 33%) minmax(0, 67%);
  }
  .mskba-page-builder .mskba-v3-venues__copy {
    grid-column: 2;
    max-width: 540px;
    margin-left: 0;
    padding-left: 0;
    isolation: isolate;
  }
  .mskba-page-builder .mskba-v3-venues__copy-shade {
    background: linear-gradient(90deg,
      rgba(2, 12, 25, .03) 0%,
      rgba(2, 12, 25, .12) 24%,
      rgba(2, 12, 25, .60) 36%,
      rgba(2, 12, 25, .63) 64%,
      rgba(2, 12, 25, .10) 100%);
  }

  /* Lower the hoop a little; its upper part may be outside the viewport. */
  .mskba-page-builder .mskba-v3-venues__hoop {
    top: 64px;
    left: -18px;
    width: clamp(225px, 16.5vw, 295px);
    z-index: 2;
  }

  /* Raise the defender so the extended arm overlaps the lower Hero edge.
     Foreground is not clipped, and its z-index is above Hero (20 > 10). */
  .mskba-page-builder .mskba-v3-venues__defender {
    left: clamp(82px, 9vw, 172px);
    width: clamp(215px, 19vw, 315px);
    top: auto;
    bottom: -20px;
    z-index: 3;
  }

  /* Shooter moves to the right of the copy. The final-ball marker is
     INSIDE this wrapper so it follows the shooter on future adjustments. */
  .mskba-page-builder .mskba-v3-venues__shooter-frame {
    position: absolute;
    z-index: 4;
    width: clamp(235px, 20vw, 345px);
    right: clamp(15px, 2.8vw, 52px);
    bottom: -105px;
    pointer-events: none;
  }
  .mskba-page-builder .mskba-v3-venues__shooter-frame > .mskba-v3-venues__shooter {
    position: relative;
    inset: auto;
    display: block;
    width: 100%;
    height: auto;
    max-width: none;
    object-fit: contain;
  }
  .mskba-page-builder .mskba-v3-venues__ball-target {
    position: absolute;
    left: 16%;        /* release hand: adjust left/right after visual QA */
    top: 7%;          /* release hand: adjust up/down after visual QA */
    width: 0;
    height: 0;
    pointer-events: none;
  }
}

/* HTML wrapper must NOT change the old tablet/mobile shooter layout.
   Mobile/tablet Venue ball handoff will be implemented in a later stage. */
@media (max-width: 1099px) {
  .mskba-page-builder .mskba-v3-venues__shooter-frame {
    display: contents;
  }
  .mskba-page-builder .mskba-v3-venues__shooter-frame > .mskba-v3-venues__shooter {
    position: absolute;
    display: block;
    max-width: none;
    height: auto;
    object-fit: contain;
    object-position: left bottom;
  }
  .mskba-page-builder .mskba-v3-venues__ball-target {
    display: none;
  }
}

