/* MSKBA / Venues Arena v3 — manual desktop correction + scroll entrance.
   Paste ONCE at the VERY END of the existing Arena v3 component CSS.
   No images, text or HTML changes. Only >= 1100px is affected.
   Scroll variables are updated by 02-scroll-entrance.js (appended to PAGE JS).
   Marker: MSKBA_MANUAL_V3_20261102 */

@media (min-width: 1100px) {
  /* The distant arena starts behind the Hero. Do not put a z-index on the
     whole #venues wrapper: Hero and players must be able to interleave. */
  .mskba-page-builder #venues,
  .mskba-page-builder #venues-scene {
    overflow: visible;
    isolation: auto;
  }
  .mskba-page-builder #venues-scene {
    position: relative;
    z-index: auto;
    --v3-hero-bleed: calc(clamp(210px, 25vw, 370px) + 100px);
    --v3-ghost-entry-x: 0vw;
    --v3-defender-entry-y: 0%;
    --v3-shooter-entry-y: 0%;
  }
  .mskba-page-builder #venues-scene .mskba-v3-venues__scene {
    z-index: 0;
    inset: calc(-1 * var(--v3-hero-bleed)) 0 0;
    overflow: hidden;
  }
  .mskba-page-builder .mskba-hero-scene {
    position: relative;
    z-index: 10;
  }

  /* Foreground sits ABOVE the Hero, with no vertical clip on the arms. */
  .mskba-page-builder #venues-scene .mskba-v3-venues__foreground {
    position: absolute;
    inset: calc(-1 * var(--v3-hero-bleed)) 0 0;
    z-index: 20;
    overflow: visible;
    pointer-events: none;
  }
  .mskba-page-builder #venues-scene .mskba-v3-venues__foreground > img {
    position: absolute;
    height: auto;
    display: block;
    max-width: none;
    object-fit: contain;
  }

  /* Text remains fully usable; its left edge is moved ~12% of the inner
     container width leftwards, leaving a column on the far right. */
  .mskba-page-builder #venues-scene .mskba-v3-venues__container {
    position: relative;
    z-index: 21;
    grid-template-columns: minmax(0, 33%) minmax(0, 67%);
  }
  .mskba-page-builder #venues-scene .mskba-v3-venues__copy {
    grid-column: 2;
    width: 100%;
    max-width: 520px;
    min-width: 0;
    padding-left: 0;
    margin-left: 0;
    isolation: isolate;
  }
  .mskba-page-builder #venues-scene .mskba-v3-venues__copy-shade {
    background: linear-gradient(90deg,
      rgba(2,12,25,.04) 0%,
      rgba(2,12,25,.12) 26%,
      rgba(2,12,25,.60) 42%,
      rgba(2,12,25,.56) 65%,
      rgba(2,12,25,.10) 100%);
  }

  /* Basket on the left, slightly lower than in the previous attempt. */
  .mskba-page-builder #venues-scene .mskba-v3-venues__hoop {
    top: 100px;
    left: -22px;
    width: clamp(225px, 16.5vw, 295px);
    z-index: 2;
  }

  /* Final, stationary positions. Their scroll entrance is only a transform;
     at progress=1 the transform is translateY(0), retaining these values. */
  .mskba-page-builder #venues-scene .mskba-v3-venues__defender {
    top: auto;
    left: clamp(75px, 8vw, 150px);
    bottom: -24px;
    width: clamp(275px, 20vw, 365px);
    z-index: 3;
    transform: translate3d(0, var(--v3-defender-entry-y), 0);
    will-change: transform;
  }

  .mskba-page-builder #venues-scene .mskba-v3-venues__shooter-frame {
    position: absolute;
    left: auto;
    top: auto;
    right: clamp(22px, 2.6vw, 52px);
    bottom: 100px;
    width: clamp(290px, 21.5vw, 390px);
    height: auto;
    z-index: 4;
    pointer-events: none;
    transform: translate3d(0, var(--v3-shooter-entry-y), 0);
    will-change: transform;
  }
  .mskba-page-builder #venues-scene .mskba-v3-venues__shooter-frame > .mskba-v3-venues__shooter {
    position: relative;
    display: block;
    inset: auto;
    width: 100%;
    height: auto;
    max-width: none;
    object-fit: contain;
    transform: none;
  }

  /* End of second-phase ball travel. Coordinates belong to the shooter
     wrapper, NOT the viewport or Hero. Fine-tune after checking the wrist. */
  .mskba-page-builder #venues-scene .mskba-v3-venues__ball-target {
    position: absolute;
    left: 21%;
    top: 8%;
    width: 0;
    height: 0;
    display: block;
    pointer-events: none;
  }
  /* One existing ball, rendered in either Hero or the scene (never both). */
  .mskba-page-builder #venues-scene .mskba-rolling-ball {
    position: absolute;
    display: block;
    visibility: visible;
    z-index: 7;
    pointer-events: none;
  }

  /* Ghost slides in from the right, stopping EXACTLY at its original
     right:0/top:-20px final placement. No opacity animation. */
  .mskba-page-builder #venues-scene .mskba-v3-venues__ghost {
    transform: translate3d(var(--v3-ghost-entry-x), 0, 0);
    will-change: transform;
  }

  /* Fade over the lower edge of the foreground athletes, not behind them. */
  .mskba-page-builder #venues-scene::after {
    z-index: 24;
  }
}

/* The old v3 shooter positions stay valid on tablet/mobile: we are NOT yet
   approving their new composition or parallax. */
@media (max-width: 1099px) {
  .mskba-page-builder #venues-scene .mskba-v3-venues__shooter-frame {
    display: contents;
  }
  .mskba-page-builder #venues-scene .mskba-v3-venues__shooter-frame > .mskba-v3-venues__shooter {
    position: absolute;
    display: block;
    max-width: none;
    height: auto;
    object-fit: contain;
    object-position: left bottom;
  }
  .mskba-page-builder #venues-scene .mskba-v3-venues__ball-target {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  .mskba-page-builder #venues-scene .mskba-v3-venues__ghost,
  .mskba-page-builder #venues-scene .mskba-v3-venues__defender,
  .mskba-page-builder #venues-scene .mskba-v3-venues__shooter-frame {
    will-change: auto;
  }
}

/* MSKBA Arena v3 — FINAL visual tune 2026-11-02 / desktop only.
   Purpose: smaller and lower players, hoop higher, ball landing visually earlier. */
@media (min-width: 1100px) {
  .mskba-page-builder #venues-scene .mskba-v3-venues__hoop {
    top: 28px;
    left: -24px;
    width: clamp(190px, 14.1vw, 255px);
    z-index: 2;
  }

  .mskba-page-builder #venues-scene .mskba-v3-venues__defender {
    left: clamp(42px, 5.4vw, 102px);
    bottom: -92px;
    width: clamp(205px, 15.2vw, 272px);
    z-index: 3;
    transform: translate3d(0, var(--v3-defender-entry-y), 0);
  }

  .mskba-page-builder #venues-scene .mskba-v3-venues__shooter-frame {
    right: clamp(2px, 0.7vw, 16px);
    bottom: -40px;
    width: clamp(220px, 15.9vw, 300px);
    z-index: 4;
    transform: translate3d(0, var(--v3-shooter-entry-y), 0);
  }

  .mskba-page-builder #venues-scene .mskba-v3-venues__shooter-frame > .mskba-v3-venues__shooter {
    width: 100%;
    height: auto;
  }

  /* Marker stays near the shooter's hand, but the final JS tune additionally
     lands the ball a bit earlier/left for the desired composition. */
  .mskba-page-builder #venues-scene .mskba-v3-venues__ball-target {
    left: 14%;
    top: 9%;
  }
}

